using Dapper;
using MdwConteudos.Api.Infrastructure;

namespace MdwConteudos.Api.Modules.Orcamentos;

public static class OrcamentoAiSchema
{
    public const string Definition = "CODORCAMENTOANALISE BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, CODORCAMENTO BIGINT NOT NULL, REVISAO INTEGER NOT NULL, VERSAOORCAMENTO BIGINT NOT NULL, STATUS VARCHAR(20) CHARACTER SET ASCII NOT NULL, ENTRADA BLOB SUB_TYPE TEXT CHARACTER SET UTF8 NOT NULL, RESULTADO BLOB SUB_TYPE TEXT CHARACTER SET UTF8, ERRO VARCHAR(500) CHARACTER SET UTF8, MODELO VARCHAR(80) CHARACTER SET ASCII NOT NULL, CODUSUARIO INTEGER NOT NULL, DTHRCRIACAO TIMESTAMP NOT NULL, DTHRINICIO TIMESTAMP, DTHRFIM TIMESTAMP, CHAVEEXECUCAO VARCHAR(36) CHARACTER SET ASCII, CONSTRAINT PK_ORCAMENTOANALISE PRIMARY KEY(CODORCAMENTOANALISE), CONSTRAINT FK_ORCAMENTOANALISE_REVISAO FOREIGN KEY(CODORCAMENTO,REVISAO) REFERENCES ORCAMENTOREVISAO(CODORCAMENTO,NUMERO), CONSTRAINT CK_ORCAMENTOANALISE_STATUS CHECK(STATUS IN ('pendente','executando','concluida','erro','cancelada','aplicada'))";
    public static async Task Migrate(IFirebirdConnectionFactory db, CancellationToken ct)
    {
        await using var c = await db.OpenConnectionAsync(ct);
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$RELATIONS WHERE RDB$RELATION_NAME='ORCAMENTOANALISE'") == 0)
            await c.ExecuteAsync(new CommandDefinition($"CREATE TABLE ORCAMENTOANALISE({Definition})", cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$INDICES WHERE RDB$INDEX_NAME='IX_ORCAMENTOANALISE_FILA'") == 0)
            await c.ExecuteAsync(new CommandDefinition("CREATE INDEX IX_ORCAMENTOANALISE_FILA ON ORCAMENTOANALISE(STATUS,CODORCAMENTOANALISE)", cancellationToken: ct));
        foreach (var (column, type) in new[] { ("ETAPA", "VARCHAR(20) CHARACTER SET ASCII DEFAULT 'analise' NOT NULL"), ("CODANALISEORIGEM", "BIGINT"), ("CONTEXTO", "BLOB SUB_TYPE TEXT CHARACTER SET UTF8") })
            if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$RELATION_FIELDS WHERE RDB$RELATION_NAME='ORCAMENTOANALISE' AND RDB$FIELD_NAME=@column", new { column }) == 0)
                await c.ExecuteAsync(new CommandDefinition($"ALTER TABLE ORCAMENTOANALISE ADD {column} {type}", cancellationToken: ct));
        if (await c.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM RDB$RELATION_CONSTRAINTS WHERE RDB$CONSTRAINT_NAME='FK_ORCANALISE_ORIGEM'") == 0)
            await c.ExecuteAsync(new CommandDefinition("ALTER TABLE ORCAMENTOANALISE ADD CONSTRAINT FK_ORCANALISE_ORIGEM FOREIGN KEY(CODANALISEORIGEM) REFERENCES ORCAMENTOANALISE(CODORCAMENTOANALISE)", cancellationToken: ct));
    }
}
